90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
114	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
120	        HttpHeaders headers = new HttpHeaders();
121	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
122	        String address = normalizeAddress(owner.getAddress());
123	        if (address.isEmpty()) {
124	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
125	        }
126	        owner.setAddress(address);
127	        if (owner.getEmail() != null) {
128	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
129	            if (!EMAIL_PATTERN.matcher(email).matches()) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	        }
134	        String telephone = normalizeTelephone(owner.getTelephone());
135	        if (telephone == null) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setTelephone(telephone);
139	        LocalDate registrationDate = resolveRegistrationDate(owner.getRegistrationDate());
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
142	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
143	        }
144	        if (isTelephoneInUse(telephone)) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        if (owner.getEmail() != null && isEmailInUse(owner.getEmail())) {
148	            return new ResponseEntity<>(HttpStatus.CONFLICT);
149	        }
150	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && isHouseholdInUse(owner)) {
151	            return new ResponseEntity<>(HttpStatus.CONFLICT);
152	        }
153	        if (countOwnersInCity(owner.getCity()) >= 50) {
154	            return new ResponseEntity<>(HttpStatus.CONFLICT);
155	        }
156	        assignRegistrationAttributes(owner);
157	        this.clinicService.saveOwner(owner);
158	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
159	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
160	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
161	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        currentOwner.setAddress(ownerFieldsDto.getAddress());
175	        currentOwner.setCity(ownerFieldsDto.getCity());
176	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	        currentOwner.setLastName(ownerFieldsDto.getLastName());
178	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
179	        String email = ownerFieldsDto.getEmail();
180	        if (email != null) {
181	            email = email.trim().toLowerCase(Locale.ROOT);
182	            if (!EMAIL_PATTERN.matcher(email).matches()) {
183	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
184	            }
185	        }
186	        currentOwner.setEmail(email);
187	        this.clinicService.saveOwner(currentOwner);
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Transactional
193	    @Override
194	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        this.clinicService.deleteOwner(owner);
200	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
