255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner != null) {
260	            Pet pet = owner.getPet(petId);
261	            if (pet != null) {
262	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	
268	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
269	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
270	
271	    /**
272	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
273	     * code are kept when present; otherwise country code '+61' is assumed and a single
274	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
275	     * stripped. The result must be a '+' followed by 8 to 15 digits.
276	     * Returns {@code null} when the number cannot form a valid E.164 value.
277	     */
278	    private static String normalizeTelephone(String telephone) {
279	        if (telephone == null) {
280	            return null;
281	        }
282	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
283	        String e164;
284	        if (cleaned.startsWith("+")) {
285	            e164 = cleaned;
286	        } else {
287	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
288	            e164 = "+61" + national;
289	        }
290	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
291	    }
292	
293	    /**
294	     * Compute and assign the derived attributes carried by a newly registered owner: the customer
295	     * code, membership number, household id, namesake count and household member count. Each is
296	     * derived from the owner's already-normalized fields and the existing owner population, so this
297	     * must run before the owner is saved, while the counts still exclude the owner being created.
298	     */
299	    private void assignRegistrationAttributes(Owner owner) {
300	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
301	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
302	        owner.setHouseholdId(householdId(owner));
303	        owner.setNamesakeCount(countNamesakes(owner));
304	        owner.setHouseholdMemberCount(countHouseholdMembers(owner));
305	    }
306	
307	    /**
308	     * Build the customer code '<CITY3>-<LAST3>-<NNNN>': CITY3 is the upper-cased first three
309	     * letters of {@code city}, LAST3 the upper-cased first three letters of {@code lastName},
310	     * and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
311	     * owners already registered in that city (e.g. 'SYD-SMI-0007').
312	     */
313	    private String generateCustomerCode(String city, String lastName) {
314	        String city3 = firstThreeLetters(city);
315	        String last3 = firstThreeLetters(lastName);
316	        int sequence = countOwnersInCity(city) + 1;
317	        return String.format("%s-%s-%04d", city3, last3, sequence);
318	    }
319	
320	    /** The upper-cased first three letters (ignoring non-letters) of {@code value}. */
321	    private static String firstThreeLetters(String value) {
322	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
323	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
324	    }
325	
326	    /**
327	     * The number of existing owners registered in {@code city}, compared case-insensitively
328	     * with collapsed whitespace.
329	     */
330	    private int countOwnersInCity(String city) {
331	        String normalized = normalizeHouseholdField(city);
332	        return (int) this.clinicService.findAllOwners().stream()
333	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalized))
334	            .count();
335	    }
336	
337	    /**
338	     * The effective registration date to store for a new owner: the date supplied on the request
339	     * when present, otherwise the current server date, in either case rolled forward to a business
340	     * day so it never falls on a weekend (a Saturday or Sunday is advanced to the following Monday).
341	     * This single point of resolution is what every registration-date-derived value (the stored
342	     * date, the membership number's year segment, the per-day create-limit) is computed from.
343	     */
344	    private static LocalDate resolveRegistrationDate(LocalDate suppliedDate) {
345	        LocalDate date = suppliedDate != null ? suppliedDate : LocalDate.now();
346	        return toBusinessDay(date);
347	    }
348	
349	    /**
350	     * Roll {@code date} forward to the next business day: a Saturday or Sunday is advanced to the
351	     * following Monday; a weekday is returned unchanged.
352	     */
353	    private static LocalDate toBusinessDay(LocalDate date) {
354	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
355	            date = date.plusDays(1);
356	        }
357	        return date;
358	    }
359	
360	    /**
361	     * Build the membership number '<customerCode>-M<YY>' where YY is the last two digits of the
362	     * {@code registrationDate} year (e.g. 'SMI-0007-M26').
363	     */
364	    private static String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
365	        String yy = String.format("%02d", registrationDate.getYear() % 100);
366	        return customerCode + "-M" + yy;
367	    }
368	
369	    /**
370	     * The number of existing owners (before this create) sharing {@code owner}'s first name and
371	     * last name, compared case-insensitively.
372	     */
373	    private int countNamesakes(Owner owner) {
374	        String firstName = normalizeHouseholdField(owner.getFirstName());
375	        String lastName = normalizeHouseholdField(owner.getLastName());
376	        return (int) this.clinicService.findAllOwners().stream()
377	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(firstName)
378	                && normalizeHouseholdField(existing.getLastName()).equals(lastName))
379	            .count();
380	    }
381	
382	    /**
383	     * Whether more than 80 owners have already been created today, i.e. carry today's (business-day
384	     * resolved) registration date. Surfaced on responses as {@code bulkSignupWarning} to flag an
385	     * unusually high daily signup volume.
386	     */
387	    private boolean isBulkSignupWarning() {
388	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > 80;
389	    }
390	
391	    /** The number of existing owners whose registration date is {@code date}. */
392	    private int countOwnersRegisteredOn(LocalDate date) {
393	        return (int) this.clinicService.findAllOwners().stream()
394	            .filter(existing -> date.equals(existing.getRegistrationDate()))
395	            .count();
396	    }
397	
398	    /** Whether any existing owner already uses the given (E.164) telephone number. */
399	    private boolean isTelephoneInUse(String telephone) {
400	        return this.clinicService.findAllOwners().stream()
401	            .map(Owner::getTelephone)
402	            .filter(existing -> existing != null)
403	            .map(OwnerRestControllerV1::normalizeTelephone)
404	            .filter(existing -> existing != null)
405	            .anyMatch(telephone::equals);
406	    }
407	
408	    /** Whether any existing owner already uses the given email, compared case-insensitively (lower-cased). */
409	    private boolean isEmailInUse(String email) {
410	        String normalized = email.trim().toLowerCase(Locale.ROOT);
411	        return this.clinicService.findAllOwners().stream()
412	            .map(Owner::getEmail)
413	            .filter(existing -> existing != null)
414	            .map(existing -> existing.trim().toLowerCase(Locale.ROOT))
415	            .anyMatch(normalized::equals);
416	    }
417	
418	    /** Common street-type abbreviations expanded during address normalization. */
419	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
420	        "ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
421	
422	    /**
423	     * Canonical stored form of an owner's address: leading/trailing whitespace trimmed, inner
424	     * whitespace collapsed to single spaces, upper-cased, with common street-type abbreviations
425	     * expanded per word ('ST' -> 'STREET', 'RD' -> 'ROAD', 'AVE' -> 'AVENUE'). Returns the empty
426	     * string when {@code address} is null or blank after normalization.
427	     */
428	    private static String normalizeAddress(String address) {
429	        if (address == null) {
430	            return "";
431	        }
432	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
433	        if (collapsed.isEmpty()) {
434	            return "";
435	        }
436	        StringBuilder sb = new StringBuilder(collapsed.length());
437	        for (String token : collapsed.split(" ")) {
438	            if (sb.length() > 0) {
439	                sb.append(' ');
440	            }
441	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(token, token));
442	        }
443	        return sb.toString();
444	    }
445	
446	    /**
447	     * Canonical form for comparing a household field: trimmed, inner whitespace collapsed
448	     * to single spaces and lower-cased, so the match is case-insensitive and whitespace-insensitive.
449	     */
450	    private static String normalizeHouseholdField(String value) {
451	        if (value == null) {
452	            return "";
453	        }
454	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
455	    }
456	
457	    /**
458	     * Existing owners that share {@code owner}'s household, i.e. have the same last name AND the
459	     * same address compared case-insensitively with collapsed whitespace.
460	     */
461	    private List<Owner> findHousemates(Owner owner) {
462	        String lastName = normalizeHouseholdField(owner.getLastName());
463	        String address = normalizeHouseholdField(owner.getAddress());
464	        return this.clinicService.findAllOwners().stream()
465	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
466	                && normalizeHouseholdField(existing.getAddress()).equals(address))
467	            .toList();
468	    }
469	
470	    /**
471	     * Whether any existing owner already shares the same household as {@code owner}, i.e. has the
472	     * same last name AND the same address compared case-insensitively with collapsed whitespace.
473	     */
474	    private boolean isHouseholdInUse(Owner owner) {
475	        return !findHousemates(owner).isEmpty();
476	    }
477	
478	    /**
479	     * The number of owners in {@code owner}'s household once this owner is created, i.e. the existing
480	     * housemates (owners sharing the same {@code householdId}) plus {@code owner} itself.
481	     */
482	    private int countHouseholdMembers(Owner owner) {
483	        return findHousemates(owner).size() + 1;
484	    }
485	
486	    /**
487	     * A stable identifier shared by every owner in the same household, i.e. every owner with the
488	     * same last name and address (compared case-insensitively with collapsed whitespace). Derived
489	     * deterministically from those normalized fields so housemates always resolve to the same value,
490	     * regardless of registration order.
491	     */
492	    private static String householdId(Owner owner) {
493	        String key = normalizeHouseholdField(owner.getLastName()) + "\n"
494	            + normalizeHouseholdField(owner.getAddress());
495	        try {
496	            byte[] digest = MessageDigest.getInstance("SHA-256")
497	                .digest(key.getBytes(StandardCharsets.UTF_8));
498	            StringBuilder sb = new StringBuilder(24);
499	            for (int i = 0; i < 12; i++) {
500	                sb.append(String.format("%02X", digest[i]));
501	            }
502	            return sb.toString();
503	        }
504	        catch (NoSuchAlgorithmException e) {
505	            throw new IllegalStateException("SHA-256 not available", e);
506	        }
507	    }
508	}
